            }
            for row in connection.execute(
                "SELECT id, slug, name, parent_id FROM career_nodes"
            )
        }
        child_counts = {
            row["parent_id"]: row["child_count"]
            for row in connection.execute(
                "SELECT parent_id, COUNT(*) AS child_count "
                "FROM career_nodes WHERE parent_id IS NOT NULL "
